parameters.inputSchema:
{
  "type": "object",
  "properties": {
    "subject": {
      "type": "string",
      "description": "The subject line of the email or main topic"
    },
    "email": {
      "type": "string",
      "description": "The body content of the email or detailed response"
    },
    "searchResults": {
      "type": "array",
      "description": "Any search results from internet queries",
      "items": {
        "type": "object",
        "properties": {
          "title": { "type": "string" },
          "url": { "type": "string" },
          "snippet": { "type": "string" }
        }
      }
    },
    "actionsTaken": {
      "type": "array",
      "description": "List of actions performed by the agent",
      "items": { "type": "string" }
    }
  },
  "required": ["subject", "email"]
}
